  Variables (tid can : Z) (R : bvmap 5 word) (M : word -> option byte).
  Hypothesis Rsp : getr R 2 = Z_to_bv 64 (bv_unsigned sp0 - 128).
  Hypothesis Rgp : getr R 3 = Z_to_bv 64 0x10800.
  Hypothesis Rtp : getr R 4 = Z_to_bv 64 0x1006b8.
  Hypothesis Mstack : stack_writable M sp0.
  Hypothesis Mimg : Forall (fun iv => img_clear M (fst iv) (snd iv)) re_ivs.
  Hypothesis Mtid : cell M 0x100610 4 tid.
  Hypothesis Htid : (0 < tid < 2 ^ 22)%Z.
  Hypothesis Mself : cell M 0x1005f0 8 0x1005f0.
  Hypothesis Mcanary : cell M 0x120928 8 can.
  Hypothesis Hcan : (0 <= can < 2 ^ 64)%Z.
  Hypothesis Mpagesz : cell M 0x120978 8 4096.
  Hypothesis Mnlocks : cell M 0x12094b 1 0.
  Hypothesis Mcells : drv_cells_ok M.

  Let E : env := ENV BL (valsRE sp0 sp0 tid can R).

  Lemma evRF_junk : forall i, (i < 32)%nat -> ev E (6 + i) = getr R (Z_to_bv 5 (Z.of_nat i)).
Proof.
